/* Public pages: Landing, Login, Terms/Privacy/etc. */
(function () {
  const { I, esc, register, ACTS, toast, seg } = P;
  const pubNav = () => `<header class="pub-nav"><div class="brand" data-go="/welcome">aust<b>wise</b></div><div class="pub-links">${['Features', 'Pricing', 'Blog', 'About'].map((x) => `<a data-go="/p/${x.toLowerCase()}">${x}</a>`).join('')}</div><div class="row"><button class="icon-btn" data-act="theme">${I('sun', 18)}</button><button class="btn primary" data-go="/login">Start for Free ${I('arrow-right', 15)}</button></div></header>`;
  const foot = () => `<footer class="pub-foot"><div class="brand">aust<b>wise</b></div><div class="row wrap" style="gap:18px">${['Terms', 'Privacy', 'Cookies', 'Docs', 'Changelog', 'Feedback'].map((x) => `<a data-go="/p/${x.toLowerCase()}">${x}</a>`).join('')}</div><span class="faint" style="font-size:12px">© 2026 AUSTWise</span></footer>`;
  const FEATS = [['layout-dashboard', 'Smart Dashboard', 'Routine, deadlines and notices in one glance.', '/dashboard'], ['chart-column', 'GradeLab', 'CGPA calculator, trends and course polls.', '/gradelab'], ['book-open', 'Resource Vault', 'Slides, notes and previous questions.', '/resource-vault'], ['file-search', 'Question Bank', 'See which topics repeat every year.', '/question-bank'], ['message-square', 'ConnectBox', 'Chat with classmates and groups.', '/connectbox'], ['wallet', 'TakaGeloKoi', 'Track every taka you spend.', '/daily-life/money-tracker'], ['map-pin', 'InsideAUST', 'Free rooms, library crowd, canteen.', '/insideaust'], ['coffee', 'DownTime', 'Trivia, games and pinboard.', '/downtime']];

  register({ path: '/welcome', title: 'Landing', group: 'Public', icon: 'rocket', bare: true, render: () => `<div class="pub">${pubNav()}
    <section class="land-hero"><div><span class="chip amber" style="height:30px;padding:0 14px">${I('sparkles', 13)}Your All-in-One Campus Companion</span><h1>Everything You Need<br><em>to Ace Your Semester</em></h1><p>AUSTWise brings together your routine, grades, question banks, resources and campus life — built by AUSTians, for AUSTians.</p>
      <div class="row wrap" style="gap:10px;margin-top:26px"><button class="btn primary lg" data-go="/login">Jump Right In ${I('arrow-right', 16)}</button><button class="btn lg" data-act="scroll-feats">Explore Features ${I('chevron-down', 16)}</button></div>
      <div class="row wrap land-stats">${[['users', '8.4k+', 'Members'], ['layers', '40+', 'Built-in features'], ['star', '15', 'Theme variants']].map(([ic, v, l]) => `<div class="row"><span class="faint">${I(ic, 18)}</span><div><div class="num" style="font-size:1.15rem">${v}</div><div class="label">${l}</div></div></div>`).join('')}</div></div>
      <div class="land-art"><div class="la-card c3"></div><div class="la-card c2"><i style="width:70%;background:var(--accent-emerald-glow)"></i><i style="width:90%"></i><i style="width:55%;background:var(--accent-rose-glow)"></i><i style="width:80%"></i></div><div class="la-card c1"><span class="ic-tile" style="width:44px;height:44px">${I('layout-grid', 22)}</span><div style="flex:1"><i style="width:75%;background:var(--text-tertiary)"></i><i style="width:95%"></i><i style="width:70%"></i></div></div></div></section>
    <section class="land-feats" id="feats"><span class="label">Features</span><h2>One app for your whole <em>campus life</em></h2><div class="grid g4">${FEATS.map(([ic, t, d, p]) => `<section class="card hoverable" data-go="${p}"><span class="ic-tile">${I(ic, 18)}</span><b style="display:block;margin:14px 0 4px">${t}</b><p class="muted" style="margin:0;font-size:12.5px;line-height:1.55">${d}</p></section>`).join('')}</div></section>
    <section class="land-cta card"><div><h2 style="margin:0 0 6px">Ready for a better semester?</h2><p class="muted" style="margin:0">Free forever for AUST students. Sign in with your Google account.</p></div><button class="btn primary lg" data-go="/login">Get started ${I('arrow-right', 16)}</button></section>
    ${foot()}</div>` });
  ACTS['scroll-feats'] = () => document.getElementById('feats').scrollIntoView({ behavior: 'smooth' });

  register({ path: '/login', title: 'Login', group: 'Public', icon: 'lock', bare: true, render: () => `<div class="pub auth"><section class="auth-card card"><div class="brand" style="text-align:center;width:auto;font-size:1.6rem">aust<b>wise</b></div><h2 style="text-align:center;margin:10px 0 4px">Welcome back</h2><p class="muted" style="text-align:center;margin:0 0 20px;font-size:13px">Sign in to continue to AUSTWise</p>
    ${seg('auth', ['Sign in', 'Sign up'], 'Sign in')}
    <div class="field" style="margin-top:16px"><span class="label">Email or Student ID</span><input class="input" placeholder="20220104001"></div><div class="field" style="margin-top:12px"><div class="row between"><span class="label">Password</span><a class="faint" style="font-size:11.5px" data-act="toast" data-msg="Reset link sent">Forgot?</a></div><input class="input" type="password" placeholder="••••••••"></div>
    <button class="btn primary" style="width:100%;height:42px;margin-top:18px" data-go="/dashboard">Sign in</button><div class="or"><span>or</span></div><button class="btn" style="width:100%;height:42px" data-go="/dashboard">${I('globe', 16)}Continue with Google</button><button class="btn ghost" style="width:100%;margin-top:8px" data-go="/dashboard">Continue as guest</button>
    <p class="faint" style="text-align:center;font-size:11px;margin:16px 0 0">Prototype — any button signs you in with sample data.</p></section></div>` });

  const DOCS = {
    features: ['Features', 'Everything inside AUSTWise', 'AUSTWise packs 40+ tools: dashboard and routine, GradeLab, Resource Vault, Question Bank Analyzer, ConnectBox, Community directories, Marketplace, InsideAUST, DownTime games and more.'],
    pricing: ['Pricing', 'Simple student pricing', 'Free forever for the essentials. Pro unlocks the Question Bank Analyzer, unlimited Vault storage and every theme.'],
    blog: ['Blog', 'Notes from the team', 'Release notes, campus guides and study tips from the AUSTWise team.'],
    about: ['About us', 'Built by AUSTians', 'AUSTWise started as a routine app for one section and grew into a campus companion used by thousands of students.'],
    terms: ['Terms of Service', 'Last updated 1 Nov 2026', 'By using AUSTWise you agree to use it for lawful academic and social purposes, respect other members and not share exam leaks.'],
    privacy: ['Privacy Policy', 'Last updated 1 Nov 2026', 'We store only what we need to run your account. Passwords in the Password Manager are encrypted on your device.'],
    cookies: ['Cookie Policy', 'Last updated 1 Nov 2026', 'We use essential cookies for sign-in only. No advertising cookies.'],
    docs: ['Docs', 'How to use AUSTWise', 'Guides for every feature: setting your routine, importing grades, uploading to the Vault and more.'],
    changelog: ['Changelog', 'What’s new', 'v4.12 — mini profile card on every avatar, Notice Board swipe actions, new masthead across Daily Life.'],
    feedback: ['Feedback', 'Tell us what to build next', ''],
  };
  register({ path: '/p', title: 'Public pages', group: 'Public', icon: 'file-text', bare: true, hidden: true, render: (sub) => {
    const [t, s, body] = DOCS[sub] || DOCS.about;
    const extra = sub === 'pricing' ? `<button class="btn primary" data-go="/see-plans">See plans ${I('arrow-right', 15)}</button>` : sub === 'feedback' ? `<section class="card" style="max-width:560px"><div class="field"><span class="label">Type</span>${seg('fb', ['Idea', 'Bug', 'Other'], 'Idea')}</div><div class="field" style="margin-top:12px"><span class="label">Message</span><textarea class="input" placeholder="I wish AUSTWise could…"></textarea></div><button class="btn primary" style="margin-top:12px" data-act="toast" data-msg="Thanks for the feedback!">Send</button></section>` : sub === 'features' ? `<div class="grid g4">${FEATS.map(([ic, ti, d, p]) => `<section class="card hoverable" data-go="${p}"><span class="ic-tile">${I(ic, 18)}</span><b style="display:block;margin:12px 0 4px">${ti}</b><p class="muted" style="margin:0;font-size:12.5px">${d}</p></section>`).join('')}</div>` : '';
    return `<div class="pub">${pubNav()}<section class="doc"><span class="label">${esc(s)}</span><h1>${esc(t)}</h1>${body ? `<p class="muted">${esc(body)}</p>` : ''}${extra}</section>${foot()}</div>`;
  } });
})();
